INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Code-Reviews nur für große Teams nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams profitieren"}, {"text": "Ja", "correct": false, "because": "Qualität immer relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Reviews?', 3, '[{"text": "Fehler früh erkennen", "correct": true, "because": "Verbessert Code-Qualität"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Nicht primär"}, {"text": "Mehr Features", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zu effektiven Code-Reviews?', 5, '[{"text": "Fehlerfindung", "correct": true, "because": "Identifiziert Bugs"}, {"text": "Standardsprüfung", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität vor Tempo"}, {"text": "UI-Design", "correct": false, "because": "Nicht Code-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Reviews verbessern Qualität. b) Sie verzögern immer Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verzögerung nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Code-Reviews?', 4, '[{"text": "Code-Qualität", "correct": false, "because": "Kern der Reviews"}, {"text": "Team-Feedback", "correct": false, "because": "Fördert Verbesserung"}, {"text": "Farbschema", "correct": true, "because": "Kein Review-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Reviews ohne Team möglich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Selbstreviews möglich"}, {"text": "Nein", "correct": false, "because": "Team üblich, nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool unterstützt Code-Reviews?', 3, '[{"text": "GitHub Pull Requests", "correct": true, "because": "Ermöglicht Feedback"}, {"text": "Compiler", "correct": false, "because": "Nur Übersetzung"}, {"text": "UI-Designer", "correct": false, "because": "Design-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Code-Reviews?', 5, '[{"text": "Fehlerreduktion", "correct": true, "because": "Bugs früh erkannt"}, {"text": "Wissensaustausch", "correct": true, "because": "Team lernt voneinander"}, {"text": "Schnellere Releases", "correct": false, "because": "Qualität vor Tempo"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Reviews fördern Teamarbeit. b) Sie sind immer zeitaufwendig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeitaufwand variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Code-Reviews?', 4, '[{"text": "Feedback", "correct": false, "because": "Kern der Reviews"}, {"text": "Standards", "correct": false, "because": "Sichern Konsistenz"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Kein Review-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Reviews ohne Standards möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Informell machbar"}, {"text": "Nein", "correct": false, "because": "Standards üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme lösen Code-Reviews?', 4, '[{"text": "Code-Fehler", "correct": true, "because": "Früh erkannt"}, {"text": "Inkonsistenzen", "correct": true, "because": "Standards durchgesetzt"}, {"text": "Langsame Tests", "correct": false, "because": "Kein Testfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Reviews nur für Senior-Entwickler sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Alle profitieren"}, {"text": "Ja", "correct": false, "because": "Teamweite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Code-Reviews?', 3, '[{"text": "Qualität", "correct": true, "because": "Kernziel der Reviews"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität vor Tempo"}, {"text": "Viele Kommentare", "correct": false, "because": "Relevanz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Reviews verbessern Code. b) Sie ersetzen Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests bleiben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben Code-Reviews?', 5, '[{"text": "Zeitaufwand", "correct": true, "because": "Durchsicht braucht Zeit"}, {"text": "Subjektivität", "correct": true, "because": "Meinungen variieren"}, {"text": "Langsamere Ausführung", "correct": false, "because": "Kein Performance-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Code-Reviews unwichtig?', 3, '[{"text": "Fehlerfindung", "correct": false, "because": "Kernziel"}, {"text": "Konsistenz", "correct": false, "because": "Standards sichern"}, {"text": "UI-Layout", "correct": true, "because": "Kein Code-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Reviews die Teamkommunikation?', 3, '[{"text": "Ja", "correct": true, "because": "Fördert Austausch"}, {"text": "Nein", "correct": false, "because": "Kommunikation steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Reviews Refactoring fördern?', 2, '[{"text": "Ja", "correct": true, "because": "Verbesserungen vorgeschlagen"}, {"text": "Nein", "correct": false, "because": "Häufige Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ergänzt Code-Reviews?', 4, '[{"text": "Qualitätssicherung", "correct": true, "because": "Sichert Standards"}, {"text": "YAGNI", "correct": false, "because": "Feature-Fokus"}, {"text": "KISS", "correct": false, "because": "Einfachheits-Fokus"}]');
